insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-gulasz', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-gulasz/3e8865b3-7bee-49c0-8406-8905d5eee76c.webp', 25, 90, 6, null, null, '{}'::jsonb, '', array['post-placki-guide', 'post-sonntagsessen', 'post-dutch-oven', 'post-kielbasa-arten', 'post-gusseisen']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-gulasz', 'de', 'Gulasz wieprzowy', 'gulasz-wieprzowy', 'Langsam geschmortes Schweinefleisch in einer dicken Paprika-Tomaten-Soße, deutlich sämiger und milder als der ungarische Gulyás und eine andere Sache als der krautige Bigos oder das schnell angebratene Gemüsegericht Leczo.', '[{"text":"Würfle das Schweinefleisch, salze und pfeffere es kräftig und brate es in heißem Öl von allen Seiten scharf an.","tip":"Brate das Fleisch in kleinen Portionen an, denn zu viel auf einmal in der Pfanne senkt die Temperatur und verhindert die Röstaromen, die später die Soße tragen."},{"text":"Gib Zwiebel und Paprika dazu und dünste beides einige Minuten mit, bis die Zwiebel glasig wird.","tip":"Schneide die Paprika in ähnlich große Stücke wie das Fleisch, dann garen beide gleichmäßig durch, ohne dass eines zu weich oder zu roh bleibt."},{"text":"Rühre Tomatenmark, Paprikapulver, Knoblauch und Lorbeer ein und lösche danach mit der Brühe ab.","tip":"Röste das Paprikapulver nur ganz kurz mit, es wird sonst schnell bitter, denn edelsüßes Pulver verträgt kaum Hitze, bevor Flüssigkeit dazukommt."},{"text":"Schmore den Gulasz zugedeckt 60 bis 90 Minuten bei milder Hitze, bis das Fleisch mit der Gabel zerfällt.","tip":"Am Vortag gekocht schmeckt der Gulasz oft noch runder, weil sich die Aromen über Nacht im Kühlschrank weiter verbinden."},{"text":"Serviere den Gulasz heiß mit frisch gebratenen Placki und einem Löffel Śmietana.","tip":"Brate die Placki erst kurz vor dem Servieren, während der Gulasz geduldig warm gehalten werden kann, mehr zur Technik im Rezept zu [Placki](/de/rezepte/placki/ziemniaczane)."}]'::jsonb, 'Gulasz wieprzowy, langsam geschmort, paprikarot, Sonntag. Der Name Gulasz kommt vom ungarischen Wort für Rinderhirte, gulyás, dessen Eintopf ursprünglich draußen auf der Steppe im Kessel über offenem Feuer gekocht wurde, lange bevor Paprika überhaupt in Europa bekannt war. Erst als die Pflanze im 19. Jahrhundert in Ungarn Fuß fasste, entstand das heute bekannte, paprikarote Gericht, wobei die Ungarn selbst zwischen der dünneren Gulyásleves-Suppe und dem dickeren Schmorgericht Pörkölt unterscheiden, bei dem gemahlene Paprika direkt im heißen Schmalz angeschwitzt wird. Der polnische Gulasz wieprzowy hat mit beiden ungarischen Varianten nur die Grundidee gemeinsam, in Polen wird die Soße meist zusätzlich mit Tomatenmark gebunden, deutlich weniger scharf gewürzt und stets sämiger und dickflüssiger als der eher brühige ungarische Gulyás gekocht, dazu kamen über die Jahrzehnte Einflüsse aus der deutschen, tschechischen und ukrainischen Küche. In vielen polnischen Haushalten in Deutschland ist Gulasz vor allem der feste Partner von [Placki](/de/rezepte/placki/ziemniaczane), ein Wochenendteller, an dem zwei eigenständige Rezepte zusammenkommen. Verwechsle den Gulasz außerdem nicht mit dem krautigen Schmorgericht [Bigos](/de/rezepte/bigos), das auf Sauerkraut statt auf Paprikasoße aufbaut, oder mit dem schnell angebratenen Paprika-Gemüse-Topf [Leczo](/de/rezepte/leczo), bei dem Gemüse und Tomate führen und nicht das langsam geschmorte Fleisch.

## Einkaufen und kochen

Nimm Schweinenacken oder Schulter, denn der Fettanteil hält das Fleisch auch nach langem Schmoren saftig. Paprika, Zwiebel, Tomatenmark und edelsüßes Paprikapulver tragen die Soße, ein guter Schmortopf oder [Dutch Oven](/de/blog/dutch-oven-kaufberatung) hilft dabei, die Hitze gleichmäßig zu halten. Kiełbasa als zusätzliche Einlage holst du bei Bedarf im [Polenladen](/de/blog/polenladen-einkaufen), wo auch das Paprikapulver oft aromatischer ist als im deutschen Supermarktregal.

Brate das Fleisch zuerst scharf an, damit Röstaromen entstehen, und röste das Paprikapulver danach nur kurz mit, sonst wird es schnell bitter. Schmore den Gulasz anschließend zugedeckt 60 bis 90 Minuten bei milder Hitze, bis sich das Fleisch mit der Gabel zerteilen lässt. Am Vortag gekocht schmeckt er oft noch runder, dann brätst du am Tag selbst nur noch frische Placki dazu und hältst den Gulasz einfach warm.

In deutschen Wohnungen riecht Gulasz nach langem Schmoren am Wochenende, ideal, wenn alle nach der Arbeitswoche hungrig ankommen und ein Topf für den ganzen Tisch reichen soll. Viele Familien bereiten ihn bewusst am Samstag vor, damit am Sonntag nur noch die Placki frisch gebraten werden müssen.

## Am Tisch

Serviere den Gulasz mit frisch gebratenen [Placki](/de/rezepte/placki/ziemniaczane) und einem Löffel Śmietana, das ist der klassische Sonntagsteller in vielen Diaspora-Haushalten. Den zusammengesetzten Teller mit Gulasch direkt auf den Puffern findest du außerdem im Rezept zu [Placek po węgiersku](/de/rezepte/placek-po-wegiersku).

Nicht angebratenes Paprikapulver, zu wenig Flüssigkeit und zu kurzes Schmoren lassen den Gulasz flach schmecken, dabei soll das Fleisch am Ende mit der Gabel zerfallen. Verwechsle Gulasz außerdem nicht mit dem schnellen Gemüsetopf [Leczo](/de/rezepte/leczo), und den zusammengesetzten Teller mit Placki obenauf findest du separat bei [Placek po węgiersku](/de/rezepte/placek-po-wegiersku).

Du kannst Kiełbasa mitschmoren, das Gericht schärfer würzen oder mit zusätzlichen Pilzen eher vegetarisch Richtung kochen. Der [Placki-Guide](/de/blog/placki-guide) hilft bei der klassischen Beilage, der [Dutch Oven](/de/blog/dutch-oven-kaufberatung) beim gleichmäßigen Schmoren. Der reine Paprika-Gemüse-Topf ohne Würfelfleisch-Marathon ist [Leczo](/de/rezepte/leczo), der zusammengesetzte Teller mit Placki als Unterlage ist [Placek po węgiersku](/de/rezepte/placek-po-wegiersku).', 'Gulasz wieprzowy Rezept | Alemniam', 'Polnischer Schweinegulasch: Schmor-Rezept bilingual mit DE-Einkauf.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-gulasz', 'pl', 'Gulasz wieprzowy', 'gulasz-wieprzowy', 'Wolno duszona wieprzowina w gęstym sosie paprykowo-pomidorowym, znacznie gęstszym i łagodniejszym niż węgierski gulyás oraz zupełnie inna od kapuścianego bigosu i szybko podsmażanego leczo.', '[{"text":"Pokrój mięso w kostkę, mocno posól i popieprz, a potem obsmaż je ze wszystkich stron na gorącym oleju.","tip":"Obsmażaj mięso w mniejszych partiach, bo za duża ilość naraz obniża temperaturę patelni i nie pozwala powstać aromatom przypieczenia, które później niosą sos."},{"text":"Dodaj cebulę i paprykę i podsmaż je razem kilka minut, aż cebula zrobi się szklista.","tip":"Pokrój paprykę na kawałki podobnej wielkości jak mięso, wtedy oba składniki dojdą równo, bez jednego zbyt miękkiego, a drugiego surowego."},{"text":"Wmieszaj koncentrat pomidorowy, paprykę w proszku, czosnek i liść laurowy, a potem zalej całość bulionem.","tip":"Podsmaż paprykę w proszku tylko bardzo krótko, inaczej szybko zgorzknieje, bo słodka papryka nie znosi długiej obróbki bez płynu."},{"text":"Duś gulasz pod przykryciem 60 do 90 minut na małym ogniu, aż mięso będzie się rozpadać pod widelcem.","tip":"Ugotowany dzień wcześniej gulasz smakuje często jeszcze pełniej, bo smaki łączą się przez noc w lodówce."},{"text":"Podawaj gulasz gorący ze świeżo usmażonymi plackami i łyżką śmietany.","tip":"Smaż placki tuż przed podaniem, podczas gdy gulasz spokojnie czeka ciepły, więcej o technice w przepisie na [placki](/pl/rezepte/placki/ziemniaczane)."}]'::jsonb, 'Gulasz wieprzowy, duszony powoli, paprykowy, niedzielny. Nazwa gulasz pochodzi od węgierskiego słowa gulyás, oznaczającego pasterza wołów, którego danie pierwotnie gotowano na stepie, w kotle nad ogniskiem, na długo przed tym, jak papryka pojawiła się w Europie. Dopiero gdy roślina zadomowiła się na Węgrzech w XIX wieku, powstało dzisiejsze, paprykowoczerwone danie, przy czym sami Węgrzy odróżniają rzadszą zupę gulyásleves od gęstszego pörköltu, w którym mielona papryka jest podsmażana bezpośrednio w gorącym smalcu. Polski gulasz wieprzowy ma z obiema węgierskimi wersjami wspólny właściwie tylko pomysł podstawowy, w Polsce sos zwykle dodatkowo zagęszcza się koncentratem pomidorowym, jest wyraźnie mniej ostry i zawsze gęstszy niż raczej zupny węgierski gulyás, a przez dekady dołączyły do tego wpływy kuchni niemieckiej, czeskiej i ukraińskiej. W wielu polskich domach w Niemczech gulasz jest przede wszystkim stałym partnerem [placków](/pl/rezepte/placki/ziemniaczane), weekendowym talerzem, na którym spotykają się dwa samodzielne przepisy. Nie myl też gulaszu z kapuścianym [bigosem](/pl/rezepte/bigos), który opiera się na kiszonej kapuście, a nie na sosie paprykowym, ani z szybko podsmażanym warzywnym garnkiem [leczo](/pl/rezepte/leczo), w którym prowadzi warzywo i pomidor, a nie długo duszone mięso.

## Zakupy i gotowanie

Weź kark albo łopatkę, bo zawartość tłuszczu utrzymuje mięso soczyste nawet po długim duszeniu. Papryka, cebula, koncentrat pomidorowy i słodka papryka w proszku niosą sos, a dobry garnek żeliwny albo [dutch oven](/pl/blog/garnek-do-duszenia) pomaga utrzymać równy żar. Kiełbasę jako dodatkową wkładkę kupisz w razie potrzeby w [sklepie polskim](/pl/blog/sklep-polski-zakupy), gdzie papryka w proszku bywa też bardziej aromatyczna niż w niemieckim markecie.

Najpierw dobrze obsmaż mięso, żeby powstały aromaty przypieczenia, a paprykę w proszku podsmaż tylko chwilę, inaczej szybko zgorzknieje. Potem duś gulasz pod przykryciem 60 do 90 minut na małym ogniu, aż mięso będzie się rozpadać pod widelcem. Ugotowany dzień wcześniej smakuje często jeszcze pełniej, wtedy w dniu podania smażysz już tylko świeże placki, a gulasz po prostu trzymasz ciepły.

W niemieckich mieszkaniach gulasz pachnie długim duszeniem w weekend, idealny, gdy wszyscy wracają głodni po tygodniu pracy, a jeden garnek ma wystarczyć dla całego stołu. Wiele rodzin gotuje go świadomie w sobotę, żeby w niedzielę smażyć już tylko świeże placki.

## Przy stole

Podawaj gulasz ze świeżo usmażonymi [plackami](/pl/rezepte/placki/ziemniaczane) i łyżką śmietany, to klasyczny niedzielny talerz w wielu domach w diasporze. Złożony talerz z gulaszem prosto na plackach znajdziesz też w przepisie na [placek po węgiersku](/pl/rezepte/placek-po-wegiersku).

Niepodsmażona papryka w proszku, za mało płynu i za krótkie duszenie spłaszczają smak gulaszu, a mięso powinno się na końcu rozpadać pod widelcem. Nie mylić gulaszu z szybkim warzywnym garnkiem [leczo](/pl/rezepte/leczo), a złożony talerz z plackami na wierzchu znajdziesz osobno w przepisie na [placek po węgiersku](/pl/rezepte/placek-po-wegiersku).

Możesz duszyć z kiełbasą, zrobić wersję ostrzejszą albo bardziej wegetariańską z dodatkiem grzybów. [Przewodnik po plackach](/pl/blog/placki-przewodnik) pomaga przy klasycznym dodatku, [garnek do duszenia](/pl/blog/garnek-do-duszenia) przy równym duszeniu. Sam warzywny gulasz paprykowy bez maratonu kostki mięsa to [leczo](/pl/rezepte/leczo), a złożony talerz z plackami jako spodem to [placek po węgiersku](/pl/rezepte/placek-po-wegiersku).', 'Gulasz wieprzowy przepis | Alemniam', 'Gulasz wieprzowy: przepis na duszone mięso, dwujęzycznie ze wskazówkami DE.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
